/*
 * oyun-mp.js v1: online play for multiplayer games on the Oyunido site. Do not edit this file.
 * Bu dosya çok oyunculu oyununu siteye bağlar. Lütfen değiştirme. Load it after oyun-sdk.js.
 *
 * The site makes the room, seats the players and starts the match. Your game never connects to a
 * server itself: it talks to the other players through these calls.
 *
 *   OyunMP.onStart(fn)        fn(match) when a match starts (again after "play again"):
 *                             match = { me, isHost, hostId, players: [{ id, nick, team, bot }],
 *                                       seed, mode: "pvp"|"pve"|"pvc", format, teams: [sizes], solo }
 *   OyunMP.isHost()           true on the one player whose game runs the match
 *   OyunMP.sendToHost(data)   a player -> the host (inputs)
 *   OyunMP.sendToAll(data)    -> everyone else (the host sends the game state)
 *   OyunMP.sendTo(id, data)   -> one player
 *   OyunMP.onMessage(fn)      fn(data, fromId)
 *   OyunMP.onHostChange(fn)   fn(isHost, hostId): the host left; if isHost, your game runs it now
 *   OyunMP.onPlayerLeft(fn)   fn(id)
 *   OyunMP.end(places)        host only: places[team] = 1 for first, 2 for second... (ties share a number)
 *   OyunMP.onEnd(fn)          fn(places) on every player
 *   OyunMP.random()           0..1, the same sequence on every player (from the match seed)
 *   OyunMP.mode               "platform" (on the site) | "preview" (opened directly)
 *
 * Preview (opened directly, e.g. with a local server):
 *   index.html                      alone against computer players, format 1v1
 *   index.html?format=2v2&mode=pvc  another format or mode
 *   index.html?room=test&players=2  open this in 2 tabs: the tabs play together (same browser only)
 */
(function () {
  "use strict";
  var VERSION = 1;
  var inFrame = window.parent !== window;
  var params = new URLSearchParams(location.search);
  var startFns = [], messageFns = [], hostFns = [], leftFns = [], endFns = [];
  var match = null;
  var rng = function () { return Math.random(); };
  var transport = null; // preview: BroadcastChannel tabs

  function emit(list, args) {
    list.forEach(function (fn) {
      try { fn.apply(null, args); } catch (e) { console.error(e); }
    });
  }

  // Small seeded generator (mulberry32): every player gets the same numbers from the same seed.
  function seeded(seed) {
    var a = seed >>> 0;
    return function () {
      a = (a + 0x6d2b79f5) >>> 0;
      var t = a;
      t = Math.imul(t ^ (t >>> 15), t | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  function begin(m) {
    match = m;
    rng = seeded(m.seed);
    emit(startFns, [m]);
  }

  function setHost(hostId) {
    if (!match) return;
    match.hostId = hostId;
    match.isHost = hostId === match.me;
    emit(hostFns, [match.isHost, hostId]);
  }

  function finish(places) {
    emit(endFns, [places]);
  }

  // --- on the site -------------------------------------------------------------------------------
  function post(message) {
    message.oyun = VERSION;
    message.type = "mp";
    window.parent.postMessage(message, "*");
  }

  if (inFrame) {
    window.addEventListener("message", function (event) {
      if (event.source !== window.parent) return;
      var msg = event.data;
      if (!msg || msg.oyun !== VERSION || msg.type !== "mp") return;
      if (msg.event === "start") begin(msg.match);
      else if (msg.event === "message") emit(messageFns, [msg.d, msg.from]);
      else if (msg.event === "host") setHost(msg.hostId);
      else if (msg.event === "left") emit(leftFns, [msg.id]);
      else if (msg.event === "end") finish(msg.places);
    });
  }

  function send(to, data) {
    if (!match || match.solo) return;
    if (inFrame) post({ op: "send", to: to, d: data });
    else if (transport) transport.send(to, data);
  }

  // --- preview -----------------------------------------------------------------------------------
  function teamsOf(format) {
    var coop = /^coop(\d+)$/.exec(format);
    return coop ? [Number(coop[1])] : format.split("v").map(Number);
  }

  function soloMatch() {
    var format = params.get("format") || "1v1";
    var mode = params.get("mode") || (format.indexOf("coop") === 0 ? "pve" : "pvc");
    var teams = teamsOf(format);
    var players = [{ id: "me", nick: params.get("player") || "Sen", team: 0, bot: false }];
    var n = 0;
    teams.forEach(function (size, team) {
      for (var i = team === 0 ? 1 : 0; i < size; i++) { n++; players.push({ id: "bot" + n, nick: "🤖 " + n, team: team, bot: true }); }
    });
    return { me: "me", isHost: true, hostId: "me", players: players, seed: Math.floor(Math.random() * 2147483647), mode: mode, format: format, teams: teams, solo: true };
  }

  // Tabs of the same browser find each other on a BroadcastChannel. The first tab is the host.
  function previewTabs(room, wanted) {
    var me = "tab" + Math.random().toString(36).slice(2, 7);
    var joinedAt = Date.now();
    var seen = {};
    seen[me] = joinedAt;
    var channel = new BroadcastChannel("oyun-mp-preview:" + room);
    transport = {
      send: function (to, data) {
        var hostId = match && match.hostId;
        channel.postMessage({ kind: "g", from: me, to: to === "host" ? hostId : to, d: data });
      },
    };
    channel.onmessage = function (e) {
      var m = e.data;
      if (m.kind === "hello") {
        seen[m.from] = m.at;
        if (!match) channel.postMessage({ kind: "hello", from: me, at: joinedAt });
        tryStart();
      } else if (m.kind === "start" && !match) {
        var copy = JSON.parse(JSON.stringify(m.match));
        copy.me = me;
        copy.isHost = copy.hostId === me;
        begin(copy);
      } else if (m.kind === "g" && match && (m.to === "all" || m.to === me)) {
        emit(messageFns, [m.d, m.from]);
      } else if (m.kind === "end") {
        finish(m.places);
      } else if (m.kind === "bye" && match) {
        emit(leftFns, [m.from]);
        if (m.from === match.hostId) {
          var rest = match.players.filter(function (p) { return !p.bot && p.id !== m.from; });
          if (rest.length) setHost(rest[0].id);
        }
      }
    };
    window.addEventListener("pagehide", function () { channel.postMessage({ kind: "bye", from: me }); });
    function tryStart() {
      var ids = Object.keys(seen).sort(function (a, b) { return seen[a] - seen[b]; });
      if (match || ids.length < wanted || ids[0] !== me) return;
      // Default: everyone for themselves (2 tabs: 1v1, 3 tabs: 1v1v1...).
      var format = params.get("format") || new Array(wanted).fill("1").join("v");
      var teams = teamsOf(format);
      var players = ids.slice(0, wanted).map(function (id, i) { return { id: id, nick: "Sekme " + (i + 1), team: i % teams.length, bot: false }; });
      var m = { hostId: me, players: players, seed: Math.floor(Math.random() * 2147483647), mode: params.get("mode") || "pvp", format: format, teams: teams, solo: false };
      channel.postMessage({ kind: "start", match: m });
      var mine = JSON.parse(JSON.stringify(m));
      mine.me = me;
      mine.isHost = true;
      begin(mine);
    }
    channel.postMessage({ kind: "hello", from: me, at: joinedAt });
    console.info("[OyunMP] preview room \"" + room + "\": waiting for " + wanted + " tabs");
    transport.end = function (places) { channel.postMessage({ kind: "end", places: places }); };
  }

  window.OyunMP = {
    version: VERSION,
    mode: inFrame ? "platform" : "preview",
    onStart: function (fn) {
      startFns.push(fn);
      if (match) { try { fn(match); } catch (e) { console.error(e); } }
    },
    onMessage: function (fn) { messageFns.push(fn); },
    onHostChange: function (fn) { hostFns.push(fn); },
    onPlayerLeft: function (fn) { leftFns.push(fn); },
    onEnd: function (fn) { endFns.push(fn); },
    isHost: function () { return !!match && match.isHost; },
    match: function () { return match; },
    sendToHost: function (data) { if (match && !match.isHost) send("host", data); },
    sendToAll: function (data) { send("all", data); },
    sendTo: function (id, data) { send(id, data); },
    random: function () { return rng(); },
    end: function (places) {
      if (!match || !match.isHost) return;
      if (!Array.isArray(places) || places.length !== match.teams.length) {
        console.warn("OyunMP.end: give one place per team, e.g. [1, 2]");
        return;
      }
      // On the site the frame shows the result and "play again".
      if (inFrame) return post({ op: "end", places: places });
      if (transport) transport.end(places);
      finish(places);
      // Preview alone: a new match a few seconds later.
      if (match.solo) setTimeout(function () { begin(soloMatch()); }, 3000);
    },
  };

  if (inFrame) {
    post({ op: "hello" });
  } else {
    var room = params.get("room");
    var wanted = Math.max(2, Math.min(10, Number(params.get("players")) || 2));
    if (room && typeof BroadcastChannel !== "undefined") previewTabs(room, wanted);
    else setTimeout(function () { begin(soloMatch()); }, 0);
  }
})();
